(x, y, t) => {
  const cx = 240, cy = 120;
  const w1x = Math.sin(x*0.02+t*0.3)*15 + Math.cos(y*0.015-t*0.2)*10;
  const w1y = Math.cos(y*0.02-t*0.25)*15 + Math.sin(x*0.018+t*0.35)*10;
  const mx = x+w1x, my = y+w1y;
  const w2x = Math.sin(my*0.025-t*0.15)*8 + Math.cos(mx*0.03+t*0.4)*6;
  const w2y = Math.cos(mx*0.022+t*0.2)*8 + Math.sin(my*0.028-t*0.3)*6;
  const sx = mx+w2x, sy = my+w2y;
  const src = [
    [240+Math.sin(t*0.6)*100, 80+Math.cos(t*0.4)*50, 0.08, 2.0],
    [320+Math.cos(t*0.5)*100, 160+Math.sin(t*0.7)*50, 0.1, 1.7],
    [240+Math.sin(t*0.3+2)*140, 120+Math.cos(t*0.5+1)*90, 0.06, 2.3],
    [120+Math.cos(t*0.8+1)*80, 180+Math.sin(t*0.6+3)*60, 0.12, 1.5],
    [360+Math.sin(t*0.4+4)*90, 60+Math.cos(t*0.9+2)*70, 0.07, 2.6],
    [240+Math.cos(t*0.35+5)*120, 200+Math.sin(t*0.55)*80, 0.09, 1.9],
    [180+Math.sin(t*0.45+3)*70, 40+Math.cos(t*0.65+2)*50, 0.11, 2.1],
    [300+Math.cos(t*0.55+1)*60, 220+Math.sin(t*0.75+4)*40, 0.085, 1.8]
  ];
  let aS=0,iS=0,wS=0;
  for(const[sX,sY,f,sp]of src){
    const d=Math.sqrt((sx-sX)**2+(sy-sY)**2);
    aS+=Math.sin(d*f-t*sp);
    iS+=Math.sin(d*f*0.7+t*sp*0.6+1.5);
    wS+=Math.sin(d*f*1.3-t*sp*0.8+3.0);
  }
  const act=aS/8,inh=iS/8,wav=wS/8;
  const bg1=Math.sin(sx*0.04+sy*0.025+t*0.8)+Math.sin(sx*0.03-sy*0.04+t*1.1);
  const bg2=Math.sin(sx*0.08+sy*0.06-t*1.3)*0.5+Math.sin(sx*0.07-sy*0.09+t*1.6)*0.5;
  const bg=(bg1+bg2)/3+Math.sin((sx+sy)*0.12+t*2.5)*0.2+Math.sin((sx-sy)*0.1-t*2)*0.2;
  const dist=Math.sqrt((sx-cx)**2+(sy-cy)**2),ang=Math.atan2(sy-cy,sx-cx);
  const spiral=(Math.sin(dist*0.05-ang*3-t*1.5)+Math.sin(dist*0.04+ang*4-t*1.2))*0.4;
  const spiral2=Math.sin(dist*0.03-ang*2+t*0.8)*Math.cos(dist*0.025+ang*5-t*1.1)*0.3;
  let minD=999,secD=999;
  for(let i=0;i<10;i++){
    const cX=240+Math.sin(i*2.399+t*0.2)*180;
    const cY=120+Math.cos(i*1.8+t*0.15)*100;
    const d=Math.sqrt((sx-cX)**2+(sy-cY)**2);
    if(d<minD){secD=minD;minD=d;}else if(d<secD)secD=d;
  }
  const voronoi=Math.sin((secD-minD)*0.15-t*0.5)*0.4;
  const react1=act-inh*0.7+bg*0.3+spiral+spiral2;
  const react2=wav*0.5+voronoi+Math.sin(react1*1.5)*0.3;
  const reaction=Math.tanh((react1+react2*0.4)*2.0);
  const cell=Math.tanh((Math.sin(sx*0.15)*Math.sin(sy*0.15)+Math.sin((sx+sy)*0.1+t)*0.5)*1.5)*0.3;
  const membrane=Math.tanh(Math.sin(minD*0.2-t*0.8)*2)*0.15;
  const pulse=0.9+Math.sin(t*0.4)*0.1;
  const blend=(reaction*0.6+cell*0.2+membrane*0.2)*pulse;
  const v=blend*0.5+0.5;
  const pal=[[6,12,52],[12,45,85],[18,85,120],[28,140,135],[45,180,155],[120,195,120],[190,185,70],[215,155,55],[220,110,65],[195,70,75],[140,40,70],[70,20,60],[6,12,52]];
  const idx=v*(pal.length-1),i=Math.min(idx|0,pal.length-2),f=idx-i;
  const sf=f*f*(3-2*f);
  const lum=0.8+Math.sin(reaction*Math.PI)*0.2;
  const edge=Math.abs(reaction)>0.7?1.15:Math.abs(reaction)>0.4?1.05:1.0;
  const glow=Math.max(0,1-Math.abs(reaction)*0.5)*0.1;
  return[
    Math.min(255,((pal[i][0]+(pal[i+1][0]-pal[i][0])*sf)*lum*edge+glow*30)|0),
    Math.min(255,((pal[i][1]+(pal[i+1][1]-pal[i][1])*sf)*lum*edge+glow*20)|0),
    Math.min(255,((pal[i][2]+(pal[i+1][2]-pal[i][2])*sf)*lum*edge+glow*40)|0)
  ];
}
